TRANSPORT="def command_bounded(argv, fd, environment, timeout=30, limit=1048576):\n    import base64\n    command_host_guard()\n\n    def drop():\n        command_host_guard()\n        if COMMAND_HOST['uid'] == 0:\n            os.setgroups([1000])\n            os.setgid(1000)\n            os.setuid(1000)\n    process = None\n    streams = {}\n    code = None\n    failure = None\n    try:\n        process = subprocess.Popen(argv, executable='/proc/self/fd/' + str(fd), pass_fds=(fd,), env=environment, preexec_fn=drop, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n        streams = {process.stdout: b'', process.stderr: b''}\n        opened = list(streams)\n        deadline = time.monotonic() + timeout\n        while opened:\n            remaining = deadline - time.monotonic()\n            if remaining <= 0:\n                raise ValueError('permission_command_timeout')\n            ready, _, _ = select.select(opened, [], [], min(remaining, 1))\n            for stream in ready:\n                remaining_bytes = limit - sum(map(len, streams.values()))\n                part = os.read(stream.fileno(), min(65536, remaining_bytes + 1))\n                if not part:\n                    opened.remove(stream)\n                    continue\n                streams[stream] += part[:remaining_bytes]\n                if len(part) > remaining_bytes:\n                    raise ValueError('permission_command_output_limit')\n        code = process.wait(timeout=max(0.01, deadline - time.monotonic()))\n    except (ValueError, OSError, subprocess.TimeoutExpired) as error:\n        failure = str(error) if isinstance(error, ValueError) and str(error) in ('permission_command_timeout', 'permission_command_output_limit') else 'permission_command_unknown'\n    finally:\n        if process is not None:\n            if process.poll() is None:\n                try:\n                    process.kill()\n                    process.wait(timeout=2)\n                except (OSError, subprocess.TimeoutExpired):\n                    failure = 'permission_command_reap_unknown'\n            rawout = streams.get(process.stdout, b'')\n            rawerr = streams.get(process.stderr, b'')\n            GETTER_RECORDS.setdefault('captures', []).append({'returncode': code, 'failure': failure, 'stdoutBase64': base64.b64encode(rawout).decode(), 'stderrBase64': base64.b64encode(rawerr).decode(), 'stdoutBytes': len(rawout), 'stderrBytes': len(rawerr)})\n            for stream in streams:\n                stream.close()\n    if failure:\n        raise ValueError(failure)\n    return {'returncode': code, 'stdoutRaw': rawout.decode('utf-8', 'strict'), 'stderrRaw': rawerr.decode('utf-8', 'strict')}\n\ndef readiness_raw(argv,timeout=30,limit=1048576,environment=None):\n if type(argv)is not list or argv[:3]!=[LAUNCH['adbPath'],'-s','emulator-5682'] or not 0<timeout<=30 or not 0<limit<=1048576:raise ValueError('readiness_command_unknown')\n before=len(GETTER_RECORDS.get('captures',[]));result=None\n try:\n  command_host_guard();external_jdk_guard();stage=getter_stage()\n  result=command_binary(Path(LAUNCH['adbPath']),LAUNCH['adbFacts']['generation'],argv[1:],LAUNCH['environment'],limit=limit,timeout=timeout)\n finally:\n  READINESS_OBSERVATIONS.append({'adb':{'argv':argv,'result':result,'captures':GETTER_RECORDS.get('captures',[])[before:]}})\n  command_host_guard();external_jdk_guard()\n  if 'stage'in locals()and getter_stage()!=stage:raise ValueError('readiness_stage_changed')\n if type(result)is not dict or type(result.get('returncode'))is not int or type(result.get('stderrRaw'))is not str or type(result.get('stdoutRaw'))is not str:raise ValueError('readiness_command_unknown')\n return result\n\ndef readiness_run(argv,timeout=30,limit=1048576,environment=None):\n result=readiness_raw(argv,timeout,limit,environment)\n if result['returncode']!=0 or result['stderrRaw']!='':raise ValueError('readiness_command_unknown')\n return result['stdoutRaw']"
